function bestRotation(nums) {
  const n = nums.length;
  const diff = new Array(n + 1).fill(0);

  for (let i = 0; i < n; i++) {
    const start = (i + 1) % n;
    const end = (i - nums[i] + n) % n;
    if (start <= end) {
      diff[start]++;
      diff[end + 1]--;
    } else {
      diff[0]++;
      diff[end + 1]--;
      diff[start]++;
      diff[n]--;
    }
  }

  let best = 0;
  let bestScore = -1;
  let score = 0;
  for (let k = 0; k < n; k++) {
    score += diff[k];
    if (score > bestScore) {
      bestScore = score;
      best = k;
    }
  }
  return best;
}

