function bestRotation(nums) {
  const n = nums.length;
  let answer = 0;
  let top = -1;
  for (let k = 0; k < n; k++) {
    const rotated = nums.slice(k).concat(nums.slice(0, k));
    let points = 0;
    rotated.forEach((value, index) => { if (value <= index) points++; });
    if (points > top) { top = points; answer = k; }
  }
  return answer;
}

