function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const mode = Math.floor(rand() * 4);
  const nums = Array.from({ length: n }, (_, i) => {
    if (mode === 0) return Math.floor(rand() * n);
    if (mode === 1) return Math.floor(rand() * Math.min(n, 3));
    if (mode === 2) return n - 1 - Math.floor(rand() * Math.min(n, 3));
    return (i + Math.floor(rand() * 3)) % n;
  });
  return [nums];
}
